def run(_context):
    import json
    import adsk.cam
    import adsk.fusion
    import adsk.core

    app = adsk.core.Application.get()
    doc = app.activeDocument

    # Find the Design product
    design = None
    for i in range(doc.products.count):
        product = doc.products.item(i)
        if product.classType() == 'adsk::fusion::Design':
            design = adsk.fusion.Design.cast(product)
            break

    root = design.rootComponent
    print(f"Component type: {type(root)}")
    print(f"Component attributes: {[x for x in dir(root) if not x.startswith('_') and 'bod' in x.lower()]}")

    # Try different ways to get bodies
    try:
        bodies = root.bodies
        print(f"bodies: {bodies}")
    except:
        print("root.bodies failed")

    try:
        bodies = root.features
        print(f"features count: {bodies.count}")
    except:
        print("root.features failed")

    # List all attributes that might contain bodies
    for attr in dir(root):
        if not attr.startswith('_') and not callable(getattr(root, attr, None)):
            try:
                val = getattr(root, attr)
                if hasattr(val, 'count'):
                    print(f"  {attr}: count={val.count}")
            except:
                pass

