def run(_context):
    import json
    import adsk.cam

    cam = mb.get_cam()
    setup = cam.setups.itemByName("Setup1")

    # Check each operation for warnings and get the actual feed values
    total_time = 0
    for i in range(setup.operations.count):
        op = setup.operations.item(i)
        print(f"\n=== {op.name} ===")

        # Check for warnings
        if hasattr(op, 'hasWarning'):
            print(f"  hasWarning: {op.hasWarning}")
        if hasattr(op, 'warning'):
            try:
                w = op.warning
                if w:
                    print(f"  warning: {w}")
            except:
                pass

        # Check actual parameter values
        params = op.parameters
        spindle = params.itemByName("tool_spindleSpeed")
        feed = params.itemByName("tool_feedCutting")
        if spindle:
            print(f"  spindle: {spindle.expression} (value: {spindle.value.value})")
        if feed:
            print(f"  feed: {feed.expression} (value: {feed.value.value})")

        # Try to get cycle time
        try:
            ct = op.machiningTime
            print(f"  machiningTime: {ct}")
            total_time += ct
        except:
            try:
                attrs = [x for x in dir(op) if 'time' in x.lower()]
                print(f"  time-related attrs: {attrs}")
            except:
                pass

    print(f"\n=== Total machining time: {total_time} ===")

